/**
 * generated by stackra gen from src/routes/*.route.ts, src/routes/*.layout.ts,
 * src/panels/*.panel.ts and the resources, documents and settings pages of the consumed manifests
 * — do not edit
 * Purpose: the full React Router 7 route tree from the `@Route`/`@Layout` classes, nested under
 *          their layouts, with the panel routes gen derived from the consumed resources, documents
 *          and settings pages in the same layout.
 * Boundary: code-based routes; a hand-written route config is banned. `toRoute` binds a class's
 *           options and body (loader, submit, guard) to the router, `document:` routes resolve the
 *           tenant's published version through `Experience.queries.GetDocument` and fall back to
 *           the class. The server re-checks permission on every call. `DashboardRoute` replaces the
 *           panel's generated index route for `tenant_admin` (reported).
 * Runtime: browser
 */
import type { RouteObject } from "react-router";
import { toLayout, toPanel, toResource, toRoute, toSettingsPage } from "@stackra/navigation/router";
import { Resources } from "#stackra/resources";
import { SettingsPages } from "#stackra/settings";
import { CustomerPortalPanel } from "#src/panels/customer-portal.panel";
import { DashboardRoute } from "#src/routes/dashboard.route";
import { NotFoundRoute } from "#src/routes/not-found.route";
import { OpenRoute } from "#src/routes/open.route";
import { PublicLayout } from "#src/routes/public.layout";
import { QuickOrderRoute } from "#src/routes/quick-order.route";
import { SettingsRoute } from "#src/routes/settings.route";
import { ShellLayout } from "#src/routes/shell.layout";
import { SignInRoute } from "#src/routes/sign-in.route";
import { WelcomeRoute } from "#src/routes/welcome.route";

/**
 * Layouts first, declared routes in declaration order, generated panel routes, the catch-all last.
 */
export const routes: RouteObject[] = [
  toLayout(PublicLayout, [toRoute(SignInRoute)]),
  // /portal: the panel's own shell with the resources it lists (orders.order)
  toPanel(CustomerPortalPanel),
  toLayout(ShellLayout, [
    toRoute(DashboardRoute), // index; shadows the generated dashboard index route
    toRoute(QuickOrderRoute),
    toRoute(SettingsRoute),
    // document: WelcomeDocument → GetDocument({ key: "console.welcome" }) or the class
    toRoute(WelcomeRoute),
    // /open?url=: the PWA protocol handler and the desktop deep link land here
    toRoute(OpenRoute),
    ...toResource(Resources.Product), // /catalogue/products, /:id, /:id/edit, /new
    ...toResource(Resources.Order), // /orders/orders, /:id
    ...toResource(Resources.AccessLogEntry), // /access-log/entries
    ...toResource(Resources.FailedJob), // /queue/failed-jobs
    ...toResource(Resources.SalesToday), // /sales
    ...toSettingsPage(SettingsPages.orders), // /settings/orders
    ...toSettingsPage(SettingsPages.inventory), // /settings/inventory
    ...toSettingsPage(SettingsPages.messages), // /settings/messages (user scope)
    toRoute(NotFoundRoute),
  ]),
];
